": "concept", "title": "Criteria"}, {"id": "c1f97231-52d0-4bff-885a-fdff8fdc1373", "type": "concept", "title": "Consensus"}, {"id": "47c7b374-0a4e-48f2-b9f6-27da4bbe78de", "type": "concept", "title": "Groupthink"}], "description": "Students learn structured approaches to avoid confusion, domination, and shallow consensus."}, {"id": "032400ab-4ea3-4b9b-b515-88737fd60153", "type": "subtopic", "title": "Collaboration and conflict", "children": [{"id": "26c6233f-edd0-4b63-9e9d-233892435174", "type": "concept", "title": "Meeting facilitation"}, {"id": "64616b14-e492-4347-a2a3-5468ebc81405", "type": "concept", "title": "Feedback"}, {"id": "1e797bd1-746d-49d5-acda-5d986c06ffc0", "type": "concept", "title": "Conflict norms"}, {"id": "ac007f2d-d659-43b6-9ec4-19595c7701b9", "type": "concept", "title": "Accountability"}], "description": "Good teamwork depends on communication practices that surface disagreement productively."}]}, {"id": "a67ede15-79c2-44bc-9f85-e1082ff9cc1e", "type": "topic", "title": "Public Speaking and Presentation Foundations", "description": "Practice audience-centered speaking through research, organization, evidence, delivery, and visual support.", "children": [{"id": "1f181599-a5a7-4f29-aa6c-70bae7c7ea20", "type": "subtopic", "title": "Audience and purpose", "children": [{"id": "eb47c6ea-65f0-4126-bdf8-9ae9f8fbee0d", "type": "concept", "title": "Audience analysis"}, {"id": "a3a5b38b-6ffb-4596-971f-7e2ee9b7a7d9", "type": "concept", "title": "Occasion"}, {"id": "f65223a0-3eec-43a9-8372-0bc2e64ee08d", "type": "concept", "title": "Thesis"}, {"id": "fcd19c49-0a25-48c8-b93c-70886878654a", "type": "concept", "title": "Speaker goal"}], "description": "Strong speeches begin with a clear purpose and a realistic understanding of audience needs."}, {"id": "49ae23fc-23f8-4706-a7d2-18ea5eb151cc", "type": "subtopic", "title": "Organization and evidence", "children": [{"id": "5882a6a9-9bfe-46c1-873b-21d654ca8899", "type": "concept", "title": "Introductions"}, {"id": "