  goal = 'Introduction to Communication',
  summary = 'Build a shared vocabulary for studying communication as process, interaction, symbolic action, and social practice. Students explain meaning through perception, identity, language, and framing; develop nonverbal skill and ethical listening; and study relationships, groups, public speaking, persuasion, media literacy, digital platforms, organizations, intercultural communication, ethics, research evidence, and career pathways.',
  data = $intcjson${"slug": "introduction-to-communication", "title": "Introduction to Communication", "description": "Build a shared vocabulary for studying communication as process, interaction, symbolic action, and social practice. Students explain meaning through perception, identity, language, and framing; develop nonverbal skill and ethical listening; and study relationships, groups, public speaking, persuasion, media literacy, digital platforms, organizations, intercultural communication, ethics, research evidence, and career pathways.", "topics": [{"id": "de66b2c2-ca69-47d6-a382-c304746d703d", "type": "topic", "title": "Communication Foundations: Models, Definitions, and Contexts", "description": "Build a shared vocabulary for studying communication as process, interaction, symbolic action, and social practice.", "children": [{"id": "c84ff0d7-c91a-4fe2-8b10-779119614a06", "type": "subtopic", "title": "What communication is", "children": [{"id": "94762dc9-4ded-441f-b4fd-de6eeda10d63", "type": "concept", "title": "Transmission"}, {"id": "814857ba-6b47-40db-b332-0d540aef27f0", "type": "concept", "title": "Interaction"}, {"id": "c69e4d96-4fca-4404-bdd5-285a9d96ff08", "type": "concept", "title": "Transaction"}, {"id": "ca4cd5b0-5e2f-4209-ae0a-1dd086367c78", "type": "concept", "title": "Symbolic action"}], "description": "Students start by seeing communication as more than sending messages; it is how people create meaning and coordinate life."}, {"id": "aa2b6cca-d0e6-4069-8649-cd650d34f8b0", "type": "subtopic", "title": "Core models", "children": [{"id": "bc8f4326-9f10-4c3f-b756-4714d160b587", "type": "concept", "title": "Sender-message-channel-receiver"}, {"id": "d61dae32-b052-4f55-a215-98dcba36923f", "type": "concept", "title": "Noise and feedback"}, {"id": "557ba931-c637-4ec7-8fcc-958184717006", "type": "concept", "title": "Encoding and decoding"}, {"id": "0db1534f-0ec9-4faa-a95c-b895ab27b854", "type": "concept", "title": "Context"}], "description": "Models give students simple maps for analyzing real communication situations."}, {"id": "6cbefa6e-955f-4b74-a9c9-df85bff90b97", "type": "subtopic", "title": "Major contexts", "children": [{"id": "88da7545-e636-453e-9a97-64a6d0f4c801", "type": "concept", "title": "Interpersonal"}, {"id": "6c5db2e7-76e3-4bf5-b48b-24a494534f67", "type": "concept", "title": "Group and organizational"}, {"id": "d2c9b5ac-2ba6-4acb-83fc-57127e3a0aa4", "type": "concept", "title": "Public"}, {"id": "8a0e7272-9861-44ca-be57-cb91c3bef9d3", "type": "concept", "title": "Mass and digital"}], "description": "The discipline becomes clearer when students can distinguish contexts while noticing how they overlap."}]}, {"id": "fe27c446-0e8b-46e0-b3ff-a0096d5ecbed", "type": "topic", "title": "Perception, Self, Identity, and Meaning-Making", "description": "Explain how people construct meaning through perception, self-concept, identity, culture, and interpretation.", "children": [{"id": "f0cc6afa-9acf-4b6e-bf92-1f0db7138040", "type": "subtopic", "title": "Perception and interpretation", "children": [{"id": "f929ecc0-96d4-4231-8045-b75f6215f7fe", "type": "concept", "title": "Selection"}, {"id": "234235bf-008e-4084-b45c-8e451a5fb3ad", "type": "concept", "title": "Organization"}, {"id": "a8403135-398c-440a-99b3-185924da1323", "type": "concept", "title": "Interpretation"}, {"id": "8320d66c-0367-4a8f-bb57-b30b054a580c", "type": "concept", "title": "Attribution"}], "description": "Perception explains why people can experience the same message differently."}, {"id": "e1d3c885-c69a-4e32-80e5-2af0137161d7", "type": "subtopic", "title": "Self and identity", "children": [{"id": "6f9c39a7-a320-4ebf-94da-108ba46bbafd", "type": "concept", "title": "Self-concept"}, {"id": "426ff508-92d4-44dc-bd1a-8d2a53b78459", "type": "concept", "title": "Social identity"}, {"id": "5f56733d-360f-408c-bc2d-59e13d93ea6c", "type": "concept", "title": "Face"}, {"id": "3952206f-bc00-4ebb-b7fe-0d761ebaef34", "type": "concept", "title": "Impression management"}], "description": "Communication both expresses and shapes who people understand themselves and others to be."}, {"id": "d6407705-a2a9-4d8a-8550-997de87d5bb4", "type": "subtopic", "title": "Meaning and social reality", "children": [{"id": "0fe901c6-ca77-4de4-8f24-ce26aef7d349", "type": "concept", "title": "Symbols"}, {"id": "8dcfd73b-084d-4bf1-b774-3955e2e55d59", "type": "concept", "title": "Frames"}, {"id": "4584eb89-44d0-4287-af7d-55b66b48ac0f", "type": "concept", "title": "Norms"}, {"id": "2318b40e-4d60-42c9-854d-2bc9b3525e02", "type": "concept", "title": "Social construction"}], "description": "Students learn that shared meanings, norms, and categories are built through interaction."}]}, {"id": "1f668431-e6b3-4155-842d-ce62738e5fce", "type": "topic", "title": "Verbal Communication, Language, and Framing", "description": "Study how words name reality, coordinate action, shape relationships, and frame public issues.", "children": [{"id": "3a5450a8-cab2-4ae2-b81d-00e8842584bb", "type": "subtopic", "title": "Language functions", "children": [{"id": "24bcc443-28b7-4838-9ad6-4ae705befcc4", "type": "concept", "title": "Denotation and connotation"}, {"id": "3701348f-953e-4f90-83f5-666ee25b3f67", "type": "concept", "title": "Speech acts"}, {"id": "6ab7ca27-efc3-4a89-9943-43e7eb1853b8", "type": "concept", "title": "Abstraction"}, {"id": "3f9266db-3e73-4115-bcdc-86b75b3adcfe", "type": "concept", "title": "Loaded language"}], "description": "Language does things: it informs, promises, persuades, labels, includes, and excludes."}, {"id": "3f8634c8-352c-4e3b-b305-e411c51cab3e", "type": "subtopic", "title": "Framing and narrative", "children": [{"id": "38b893ee-78b1-4863-99da-120d30c2aa24", "type": "concept", "title": "Issue framing"}, {"id": "b0c07ae7-56b7-420c-a7d3-c732be23ea79", "type": "concept", "title": "Metaphor"}, {"id": "b1221e3b-0e71-4ac1-aa7c-59d1ec967390", "type": "concept", "title": "Narrative structure"}, {"id": "4d7219ed-d710-4168-b4e5-b45d63f8cdf5", "type": "concept", "title": "Problem definition"}], "description": "Frames and stories shape what audiences notice and what responses seem reasonable."}, {"id": "c6e7a729-072b-417a-a4bc-aad9b4979011", "type": "subtopic", "title": "Responsible language use", "children": [{"id": "c4a43004-ee11-4088-94fa-4d237b967735", "type": "concept", "title": "Plain language"}, {"id": "ba6f8f80-e4fa-4b2e-9304-7d2683092844", "type": "concept", "title": "Inclusive language"}, {"id": "c939d83c-6642-4499-862b-2d98eb096778", "type": "concept", "title": "Credibility"}, {"id": "abaa7997-f69a-44ea-968d-6f222279b801", "type": "concept", "title": "Context sensitivity"}], "description": "Students practice language choices that are clear, accurate, inclusive, and audience-aware."}]}, {"id": "a5233018-0317-44c7-addc-0a1ea4f5e94f", "type": "topic", "title": "Nonverbal Communication and Listening", "description": "Develop skill in interpreting and using nonverbal cues while practicing active, ethical listening.", "children": [{"id": "72747bf1-abc4-4a0e-8518-8a3353d04a99", "type": "subtopic", "title": "Nonverbal channels", "children": [{"id": "eebaaa47-8498-498b-a6cc-852bc571cfc3", "type": "concept", "title": "Facial expression"}, {"id": "d17d83fa-e611-4d01-a97f-0f810bd5cc2d", "type": "concept", "title": "Gesture"}, {"id": "4b6a2672-53fa-405a-b511-d18750cb7643", "type": "concept", "title": "Eye contact"}, {"id": "b5625c58-89c0-4119-9881-6765cb696bb0", "type": "concept", "title": "Space and touch"}], "description": "Nonverbal cues help create meaning, regulate interaction, and communicate emotion or status."}, {"id": "9d5e73c9-b495-4748-85b0-c8e10795d041", "type": "subtopic", "title": "Listening as active work", "children": [{"id": "3b4a8990-8afd-4141-8b0e-f8f5b87ed471", "type": "concept", "title": "Attending"}, {"id": "1b9e9ab2-94e5-436e-a13d-e7fd53aa74e6", "type": "concept", "title": "Paraphrasing"}, {"id": "e47a52f9-87c1-4c51-a8ea-d63a6d5e717c", "type": "concept", "title": "Questioning"}, {"id": "7fff3918-1e23-4b17-a611-be17307f9a11", "type": "concept", "title": "Reflective response"}], "description": "Listening is not passive; it is a learned process of attention, interpretation, empathy, and response."}, {"id": "8fb04120-5cc4-4da7-bb65-1f035265547f", "type": "subtopic", "title": "Misinterpretation and context", "children": [{"id": "acdf2816-5b45-443e-847f-ec663dc49c03", "type": "concept", "title": "Ambiguity"}, {"id": "98657497-bc27-4080-b2c1-7cdcf7cdfbc0", "type": "concept", "title": "Cultural variation"}, {"id": "2a1ed91b-49e2-4f1e-879a-a587b989ec07", "type": "concept", "title": "Status cues"}, {"id": "f5f5b4dc-bc6b-474b-acc0-358d74601c58", "type": "concept", "title": "Digital nonverbal substitutes"}], "description": "Nonverbal meaning depends heavily on culture, relationship, setting, and power."}]}, {"id": "e4a48738-7b01-4bdd-af7c-8c05b9d69dfd", "type": "topic", "title": "Interpersonal Communication and Relationships", "description": "Understand how communication forms, maintains, repairs, and sometimes harms personal relationships.", "children": [{"id": "2a0ae9af-caaa-4669-8609-2463ead3b7f6", "type": "subtopic", "title": "Relationship development", "children": [{"id": "0569785a-df0f-45f4-a582-97f7eafce561", "type": "concept", "title": "Initiating"}, {"id": "52be9e1a-10ca-4e12-9d51-5174f64d2a35", "type": "concept", "title": "Self-disclosure"}, {"id": "925fa324-3fae-4b6f-90c7-316a217c48d5", "type": "concept", "title": "Relational maintenance"}, {"id": "1987c9ea-3270-4d39-bed7-8e41e7474ee9", "type": "concept", "title": "Boundary management"}], "description": "Students learn how relationships begin, deepen, stabilize, and sometimes dissolve through communication."}, {"id": "8baabad6-c2fb-4f49-b380-397b73a05a0a", "type": "subtopic", "title": "Conflict and repair", "children": [{"id": "1c3611ef-7eb9-4dd8-b6ff-755227fb2013", "type": "concept", "title": "Conflict styles"}, {"id": "51433598-503b-4448-93f4-97f9b5d62da7", "type": "concept", "title": "Defensiveness"}, {"id": "47b54a27-bbae-496d-b582-5c4143edbcae", "type": "concept", "title": "I-statements"}, {"id": "5d5020b9-ff64-4ee9-b28a-1b0fbc8b96d1", "type": "concept", "title": "Apology and repair"}], "description": "Conflict becomes more manageable when students can identify patterns and repair strategies."}, {"id": "fb9e539f-b709-417d-97da-02a2ad64a0c6", "type": "subtopic", "title": "Emotion and support", "children": [{"id": "c8d16d18-a940-49b7-9e19-5cd245912fdd", "type": "concept", "title": "Empathy"}, {"id": "6da7193b-856b-44dc-8fa0-23ffcf4e3b88", "type": "concept", "title": "Validation"}, {"id": "2fcb1cb1-bedb-46e7-ba4b-1c37cfd6d100", "type": "concept", "title": "Supportive messages"}, {"id": "085270e2-e815-4e8b-ab09-7f7ce1fa2975", "type": "concept", "title": "Relational ethics"}], "description": "Interpersonal competence includes responding to emotion with care, clarity, and boundaries."}]}, {"id": "7c18a432-cb0b-4b6c-b733-6c2db5c2b6cf", "type": "topic", "title": "Group and Team Communication", "description": "Learn how people coordinate roles, norms, decisions, conflict, and collaboration in small groups.", "children": [{"id": "cf451d75-fa8c-4f82-b533-d9a6b2fd81ce", "type": "subtopic", "title": "Group formation and roles", "children": [{"id": "00041838-6675-4f99-9748-98db8056f0d9", "type": "concept", "title": "Task roles"}, {"id": "6633f7c1-39cc-41f8-83ab-32f4dbe0790a", "type": "concept", "title": "Relational roles"}, {"id": "b03212ab-78ce-4199-8dd5-03a1216e483e", "type": "concept", "title": "Norms"}, {"id": "cdbb7cff-7761-430d-9759-8697a3d610c3", "type": "concept", "title": "Group socialization"}], "description": "Groups work better when members understand roles, norms, expectations, and participation patterns."}, {"id": "6759f555-799b-47e4-970c-1ea7bbbe0be6", "type": "subtopic", "title": "Decision-making", "children": [{"id": "6568057a-34b1-4a5b-8082-bc66c374c5c3", "type": "concept", "title": "Problem definition"}, {"id": "e3810114-727b-4b08-8129-255b061deaa3", "type": "concept", "title": "Criteria"}, {"id": "c1f97231-52d0-4bff-885a-fdff8fdc1373", "type": "concept", "title": "Consensus"}, {"id": "47c7b374-0a4e-48f2-b9f6-27da4bbe78de", "type": "concept", "title": "Groupthink"}], "description": "Students learn structured approaches to avoid confusion, domination, and shallow consensus."}, {"id": "032400ab-4ea3-4b9b-b515-88737fd60153", "type": "subtopic", "title": "Collaboration and conflict", "children": [{"id": "26c6233f-edd0-4b63-9e9d-233892435174", "type": "concept", "title": "Meeting facilitation"}, {"id": "64616b14-e492-4347-a2a3-5468ebc81405", "type": "concept", "title": "Feedback"}, {"id": "1e797bd1-746d-49d5-acda-5d986c06ffc0", "type": "concept", "title": "Conflict norms"}, {"id": "ac007f2d-d659-43b6-9ec4-19595c7701b9", "type": "concept", "title": "Accountability"}], "description": "Good teamwork depends on communication practices that surface disagreement productively."}]}, {"id": "a67ede15-79c2-44bc-9f85-e1082ff9cc1e", "type": "topic", "title": "Public Speaking and Presentation Foundations", "description": "Practice audience-centered speaking through research, organization, evidence, delivery, and visual support.", "children": [{"id": "1f181599-a5a7-4f29-aa6c-70bae7c7ea20", "type": "subtopic", "title": "Audience and purpose", "children": [{"id": "eb47c6ea-65f0-4126-bdf8-9ae9f8fbee0d", "type": "concept", "title": "Audience analysis"}, {"id": "a3a5b38b-6ffb-4596-971f-7e2ee9b7a7d9", "type": "concept", "title": "Occasion"}, {"id": "f65223a0-3eec-43a9-8372-0bc2e64ee08d", "type": "concept", "title": "Thesis"}, {"id": "fcd19c49-0a25-48c8-b93c-70886878654a", "type": "concept", "title": "Speaker goal"}], "description": "Strong speeches begin with a clear purpose and a realistic understanding of audience needs."}, {"id": "49ae23fc-23f8-4706-a7d2-18ea5eb151cc", "type": "subtopic", "title": "Organization and evidence", "children": [{"id": "5882a6a9-9bfe-46c1-873b-21d654ca8899", "type": "concept", "title": "Introductions"}, {"id": "b10f12b6-ffc5-454f-9e44-59baeb95e817", "type": "concept", "title": "Main points"}, {"id": "d3cccb5b-6431-436f-a35e-c3767e029e97", "type": "concept", "title": "Transitions"}, {"id": "8116ad1e-f984-40b9-bfd8-d19db82be424", "type": "concept", "title": "Oral citations"}], "description": "Students learn to build speeches that audiences can follow, trust, and remember."}, {"id": "d1705cff-869c-4e2a-84e2-4c578d543c75", "type": "subtopic", "title": "Delivery and visual support", "children": [{"id": "d0113efd-d98e-4a12-a8c3-814608f8adfb", "type": "concept", "title": "Voice"}, {"id": "40ff9c96-3b67-4980-866f-940ae1d3e1a3", "type": "concept", "title": "Movement"}, {"id": "5ecde48a-3cf4-4a3d-85a2-ae4e83b35a73", "type": "concept", "title": "Slides"}, {"id": "e84b3dea-0d78-4b7c-9065-f07ae9353d82", "type": "concept", "title": "Practice and feedback"}], "description": "Delivery turns prepared content into a live, embodied communication event."}]}, {"id": "f6b0944c-e23f-4b93-a573-819fe3e88077", "type": "topic", "title": "Persuasion, Rhetoric, and Argument", "description": "Analyze how communicators influence attitudes and action through credibility, emotion, evidence, framing, and ethics.", "children": [{"id": "a26e0277-f1e7-46ba-9828-28c5dbb737f3", "type": "subtopic", "title": "Rhetorical appeals", "children": [{"id": "502d53dd-01cd-46cf-ba5b-689e5b3f2ff9", "type": "concept", "title": "Ethos"}, {"id": "64d74421-f21e-4c28-bb17-fe88f590db03", "type": "concept", "title": "Pathos"}, {"id": "683f3029-b4aa-4e6b-8a0c-549cd81a5b2d", "type": "concept", "title": "Logos"}, {"id": "721d1919-4f3f-47fc-955a-3f6366c54b88", "type": "concept", "title": "Kairos"}], "description": "Rhetoric provides a practical vocabulary for how influence works."}, {"id": "d05c9068-c8aa-4f53-a633-0275723f1a3f", "type": "subtopic", "title": "Argument quality", "children": [{"id": "f1aff35f-4c96-497e-b4d5-01f4f3f3e8e7", "type": "concept", "title": "Claims"}, {"id": "f10aadf6-92a8-44d6-b5f1-27aa376ca5aa", "type": "concept", "title": "Reasons"}, {"id": "a06a87b7-20a0-49e4-8366-9a6983bec60e", "type": "concept", "title": "Evidence"}, {"id": "2c35ae59-f5c5-4295-ad84-62ee22887182", "type": "concept", "title": "Warrants"}], "description": "Students learn to evaluate claims and evidence instead of treating persuasion as mere performance."}, {"id": "01e83d7b-64ee-4f3c-bf89-f91837806c87", "type": "subtopic", "title": "Ethical persuasion", "children": [{"id": "d338c7f4-afbd-4129-a1f6-2255ec0fb700", "type": "concept", "title": "Transparency"}, {"id": "de45495c-523f-4f62-9e1f-35d9062851d1", "type": "concept", "title": "Manipulation"}, {"id": "42868f25-84a0-418b-a424-056dffd88e74", "type": "concept", "title": "Fallacies"}, {"id": "69032e4b-e116-4f97-bbee-adc893ed0135", "type": "concept", "title": "Responsible advocacy"}], "description": "Influence should respect audience agency, truthfulness, and the consequences of messages."}]}, {"id": "fe1db250-ca5a-47aa-ab40-2106a132e0fa", "type": "topic", "title": "Mass Communication, Media Literacy, and Journalism", "description": "Introduce media systems, audiences, news, entertainment, advertising, media effects, and critical media literacy.", "children": [{"id": "eda9164e-ec3c-42d9-bc7b-623747398462", "type": "subtopic", "title": "Media systems", "children": [{"id": "c77175a1-2d8f-4447-84c6-28cda732e109", "type": "concept", "title": "Print"}, {"id": "7e9144fa-6013-4944-a2a3-aaee8628a74f", "type": "concept", "title": "Broadcast"}, {"id": "e2134b3d-86f3-4b4d-b0ee-cdaeb8faa199", "type": "concept", "title": "Streaming"}, {"id": "5a48d784-4255-4fa6-a0ff-8a723b693316", "type": "concept", "title": "Advertising and PR"}], "description": "Students learn how media industries produce and distribute information, entertainment, and advertising."}, {"id": "cfe4aa97-d743-41c0-a593-b56015a4b1bf", "type": "subtopic", "title": "Media effects and audiences", "children": [{"id": "f0836d8e-e68a-4581-81d6-890144186614", "type": "concept", "title": "Agenda setting"}